import{_ as h,o as t,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Assessment Experience là gì","description":"","frontmatter":{},"headers":[],"relativePath":"learning/assessment-experience.md","filePath":"learning/assessment-experience.md"}'),c={name:"learning/assessment-experience.md"};function g(e,n,o,r,u,l){return t(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="assessment-experience-la-gi" tabindex="-1">Assessment Experience là gì <a class="header-anchor" href="#assessment-experience-la-gi" aria-label="Permalink to &quot;Assessment Experience là gì&quot;">​</a></h1><p>Trên trang này# Assessment Experience là gì <a href="#assessment-experience-la-gi">​</a> Một Assessment Experience không dạy. Nó tồn tại để trả lời một câu duy nhất: <strong>hệ thống còn cần biết gì về learner này?</strong> Đây là chỗ Nemo12 lệch xa nhất khỏi trực giác thông thường. Với hầu hết mọi người, &quot;kiểm tra&quot; nghĩa là chấm điểm — cho một con số nói learner làm được bao nhiêu phần trăm. Với Nemo12, kiểm tra là <strong>thu thập thông tin</strong>, và con số cuối cùng gần như là sản phẩm phụ.</p><h2 id="bai-đo-tot-la-bai-giam-đuoc-nhieu-bat-đinh-nhat-​" tabindex="-1">Bài đo tốt là bài giảm được nhiều bất định nhất <a href="#bai-đo-tot-la-bai-giam-đuoc-nhieu-bat-đinh-nhat">​</a> <a class="header-anchor" href="#bai-đo-tot-la-bai-giam-đuoc-nhieu-bat-đinh-nhat-​" aria-label="Permalink to &quot;Bài đo tốt là bài giảm được nhiều bất định nhất [​](#bai-đo-tot-la-bai-giam-đuoc-nhieu-bat-đinh-nhat)&quot;">​</a></h2><p>Hệ thống chọn câu hỏi tiếp theo bằng cách cân nhắc năm yếu tố: textGiá trị của một câu hỏi = Lượng thông tin thu được × Mức liên quan tới mục tiêu của learner × Tầm quan trọng của kỹ năng đó × Khả năng phân biệt (câu này có tách được hai giả thuyết không?) ÷ Chi phí (thời gian, tải nhận thức, mệt mỏi)Hệ quả trực tiếp: <strong>một câu hỏi mà hệ thống đã biết chắc learner làm được thì gần như vô giá trị</strong>, dù nó &quot;đúng chương trình&quot; tới đâu. Nó không giảm bất định nào cả, mà vẫn tốn thời gian và sức của con. Đây là lý do một bài đo trên Nemo12 có thể chỉ có 6 câu trong khi bài kiểm tra ở trường có 40 câu — và bài 6 câu lại nói được nhiều hơn về con. Bài 40 câu dành phần lớn dung lượng để xác nhận lại những thứ đã rõ.</p><h2 id="bai-đo-dung-khi-đu-chac-chan-khong-dung-khi-het-cau-​" tabindex="-1">Bài đo dừng khi đủ chắc chắn, không dừng khi hết câu <a href="#bai-đo-dung-khi-đu-chac-chan-khong-dung-khi-het-cau">​</a> <a class="header-anchor" href="#bai-đo-dung-khi-đu-chac-chan-khong-dung-khi-het-cau-​" aria-label="Permalink to &quot;Bài đo dừng khi đủ chắc chắn, không dừng khi hết câu [​](#bai-đo-dung-khi-đu-chac-chan-khong-dung-khi-het-cau)&quot;">​</a></h2><p>Một bài kiểm tra truyền thống có độ dài cố định: 40 câu cho mọi học sinh. Nemo12 làm ngược lại — bài đo <strong>dừng khi độ chắc chắn của kết luận đã đạt ngưỡng cần thiết</strong>. Với một learner trả lời nhất quán, ngưỡng đó đến rất nhanh. Với một learner có kết quả thất thường, hệ thống hỏi thêm — vì sự thất thường tự nó là thông tin cần làm rõ, không phải thứ để làm tròn thành một con số trung bình. Vì sao điều này quan trọng với gia đình Thời gian và sức tập trung của một đứa trẻ là tài nguyên hữu hạn. Mỗi phút dùng để xác nhận điều đã biết là một phút không dùng để học điều chưa biết. Bài đo ngắn không phải để dễ dãi — nó để dành thời gian cho việc học.</p><h2 id="tra-loi-đung-khong-tu-đong-la-bang-chung-cua-viec-biet-​" tabindex="-1">Trả lời đúng không tự động là bằng chứng của việc biết <a href="#tra-loi-đung-khong-tu-đong-la-bang-chung-cua-viec-biet">​</a> <a class="header-anchor" href="#tra-loi-đung-khong-tu-đong-la-bang-chung-cua-viec-biet-​" aria-label="Permalink to &quot;Trả lời đúng không tự động là bằng chứng của việc biết [​](#tra-loi-đung-khong-tu-đong-la-bang-chung-cua-viec-biet)&quot;">​</a></h2><p>Nemo12 không chỉ nhìn đáp án. Hệ thống nhìn cả <strong>cách trả lời</strong>:</p><ul><li><strong>Thời gian trả lời.</strong> Đúng sau 2 giây ở một bài cần 90 giây suy nghĩ là dấu hiệu đoán, không phải dấu hiệu giỏi.</li><li><strong>Mức tự tin learner tự khai.</strong> Đúng nhưng khai &quot;không chắc&quot; khác hẳn đúng và khai &quot;chắc chắn&quot;.</li><li><strong>Learner tự nói mình đã làm thế nào.</strong> Sau khi chọn đáp án, con được hỏi lý do: tự suy ra, nhớ lại, loại trừ, hay đoán. Con tự khai &quot;đoán&quot; mà vẫn đúng thì <strong>không được tính là bằng chứng của việc nhớ độc lập</strong>.</li><li><strong>Chuỗi trả lời nhanh liên tiếp.</strong> Ba câu liền trả lời chớp nhoáng với tỷ lệ đúng ngang mức ngẫu nhiên → hệ thống gần như bỏ qua toàn bộ dữ liệu đó thay vì kết luận &quot;learner yếu&quot;. Điểm cuối cùng đáng nhấn mạnh. Khi một đứa trẻ bấm bừa cho xong, hệ thống truyền thống sẽ ghi nhận &quot;mastery 25%&quot; và bắt con học lại thứ con đã biết — một hình phạt cho việc chán, không phải cho việc không biết. Nemo12 đánh dấu phiên đó là <strong>không đủ dữ liệu đáng tin</strong> và hẹn đo lại vào lúc khác.</li></ul><h2 id="khi-he-thong-can-thiep-no-tang-dan-chu-khong-phat-​" tabindex="-1">Khi hệ thống can thiệp, nó tăng dần chứ không phạt <a href="#khi-he-thong-can-thiep-no-tang-dan-chu-khong-phat">​</a> <a class="header-anchor" href="#khi-he-thong-can-thiep-no-tang-dan-chu-khong-phat-​" aria-label="Permalink to &quot;Khi hệ thống can thiệp, nó tăng dần chứ không phạt [​](#khi-he-thong-can-thiep-no-tang-dan-chu-khong-phat)&quot;">​</a></h2><p>Nếu phát hiện learner đang trả lời bừa, thứ tự xử lý là:</p><ul><li>Nhắc nhẹ: &quot;chậm lại, đọc kỹ đề&quot;.</li><li>Đưa ra nút <strong>&quot;Chưa biết&quot;</strong> như một lựa chọn hợp lệ — trả lời trung thực có giá trị hơn đoán bừa.</li><li>Hỏi mức tự tin.</li><li>Thêm một khoảng chờ rất ngắn trước khi cho nộp.</li><li>Đánh dấu cả bài là không đủ dữ liệu tin cậy. Không bước nào là trừng phạt, và không bước nào báo cho phụ huynh rằng &quot;con đang lười&quot;. Một đứa trẻ bấm bừa thường đang mệt, đang chán, hoặc đang thấy bài quá xa tầm — cả ba đều là vấn đề thiết kế của hệ thống trước khi là vấn đề thái độ của con.</li></ul><h2 id="bai-đo-cung-can-đuoc-kiem-đinh-​" tabindex="-1">Bài đo cũng cần được kiểm định <a href="#bai-đo-cung-can-đuoc-kiem-đinh">​</a> <a class="header-anchor" href="#bai-đo-cung-can-đuoc-kiem-đinh-​" aria-label="Permalink to &quot;Bài đo cũng cần được kiểm định [​](#bai-đo-cung-can-đuoc-kiem-đinh)&quot;">​</a></h2><p>Câu hỏi dùng để đo phải qua quy trình riêng: đăng ký vào kho, được review, được kiểm tra xem có thật sự phân biệt được learner biết và không biết. Một câu hỏi mà cả người giỏi lẫn người kém đều làm sai như nhau thì không đo được gì — nó chỉ đang đo độ khó của cách diễn đạt. Assessment không phải phiên toà. Nó là cách hệ thống thừa nhận rằng mình chưa biết đủ về con bạn, và đi hỏi thêm. <a href="/learning/assessment-khac-learning">Vì sao Assessment không đồng nghĩa với Learning →</a></p>',14)])])}const k=h(c,[["render",g]]);export{m as __pageData,k as default};
